; keep.asm -- chapter 12: the caller's registers kept two ways
; generated by gen12.py
        INCLUDE "msx.inc"
        OUTPUT "keep.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
; Two routines that do the same work and give the caller back its
; registers: keep1 with PUSH and POP, keep2 with the second set.
init:   di
        ld sp, SYS_AREA         ; the stack below the BIOS's work area
        ld hl, $1234
        push hl
        pop af                  ; AF = $1234 (chapter 8)
        ld bc, $5678
        ld de, $9ABC
        ld hl, $DEF0
k1:     call keep1
k2:     call keep2
k3:     nop
stop:   jr stop

; keep1: changes every register and gives the caller its own back
keep1:  push af
        push bc
        push de
        push hl
        ld a, $AA               ; the work: every register changed
        or a                    ; F too
        ld bc, $BBBB
        ld de, $DDDD
        ld hl, $4444
        pop hl                  ; the last pushed comes back first
        pop de
        pop bc
        pop af
        ret

; keep2: the same work, with the caller's registers in the second set
keep2:  ex af, af'
        exx
        ld a, $AA
        or a
        ld bc, $BBBB
        ld de, $DDDD
        ld hl, $4444
        exx
        ex af, af'
        ret
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
